# WAR ARENA — wallet-watch subscription TIERS (Free 1 / Pro $9.99 = 10 / Elite $29.99 = 50)
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-watch-tiers.ps1
$ErrorActionPreference = 'Stop'
Write-Host 'Installing tier-based wallet-watch pricing...' -ForegroundColor Cyan

if (-not (Test-Path 'migrations')) { New-Item -ItemType Directory -Force -Path 'migrations' | Out-Null }
if (-not (Test-Path 'src\product\pricing')) { New-Item -ItemType Directory -Force -Path 'src\product\pricing' | Out-Null }
if (-not (Test-Path 'src\product\watch')) { New-Item -ItemType Directory -Force -Path 'src\product\watch' | Out-Null }
if (-not (Test-Path 'src\product\persistence\pg')) { New-Item -ItemType Directory -Force -Path 'src\product\persistence\pg' | Out-Null }
if (-not (Test-Path 'src\api')) { New-Item -ItemType Directory -Force -Path 'src\api' | Out-Null }

# ---- migrations/0005_watch_tiers.sql ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'migrations\0005_watch_tiers.sql'), [Convert]::FromBase64String($b64))
Write-Host '  wrote migrations/0005_watch_tiers.sql' -ForegroundColor Green

# ---- src/product/pricing/pricing.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\product\pricing\pricing.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/product/pricing/pricing.ts' -ForegroundColor Green

# ---- src/product/watch/walletWatchStore.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\product\watch\walletWatchStore.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/product/watch/walletWatchStore.ts' -ForegroundColor Green

# ---- src/product/persistence/pg/pgWalletWatchStore.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\product\persistence\pg\pgWalletWatchStore.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/product/persistence/pg/pgWalletWatchStore.ts' -ForegroundColor Green

# ---- src/api/wiredApp.ts ----
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\api\wiredApp.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/api/wiredApp.ts' -ForegroundColor Green

Write-Host 'Also replace miniapp/index.html with the exported file.' -ForegroundColor Yellow
Write-Host 'Done. Run:  npm run build; npm test' -ForegroundColor Cyan